// SKIP LIST implementation
const MAX_LEVEL = 16; // log2(max n) levels

class SkipNode {
    constructor(key, val, level) {
        this.key = key;
        this.val = val;
        this.forward = new Array(level + 1).fill(null); // forward[i] = next at level i
    }
}

class SkipList {
    constructor() {
        this.header = new SkipNode(-Infinity, null, MAX_LEVEL);
        this.level = 0; // current max level in use
    }

    _randomLevel() {
        let lvl = 0;
        while (Math.random() < 0.5 && lvl < MAX_LEVEL) lvl++;
        return lvl;
    }

    // SEARCH: O(log n) expected
    search(key) {
        let curr = this.header;
        for (let i = this.level; i >= 0; i--) {
            while (curr.forward[i] && curr.forward[i].key < key) {
                curr = curr.forward[i]; // advance at level i
            }
        }
        curr = curr.forward[0]; // final step at level 0
        return (curr && curr.key === key) ? curr.val : undefined;
    }

    // INSERT: O(log n) expected
    insert(key, val) {
        const update = new Array(MAX_LEVEL + 1).fill(this.header);
        let curr = this.header;

        // Find insertion point at each level
        for (let i = this.level; i >= 0; i--) {
            while (curr.forward[i] && curr.forward[i].key < key) {
                curr = curr.forward[i];
            }
            update[i] = curr;
        }

        curr = curr.forward[0];
        if (curr && curr.key === key) { curr.val = val; return; } // update

        const newLevel = this._randomLevel();
        if (newLevel > this.level) {
            for (let i = this.level + 1; i <= newLevel; i++) update[i] = this.header;
            this.level = newLevel;
        }

        const newNode = new SkipNode(key, val, newLevel);
        for (let i = 0; i <= newLevel; i++) {
            newNode.forward[i] = update[i].forward[i];
            update[i].forward[i] = newNode;
        }
    }
}

const sl = new SkipList();
sl.insert(3, 'three');
sl.insert(1, 'one');
sl.insert(5, 'five');
sl.insert(2, 'two');
console.log(sl.search(3)); // 'three'
console.log(sl.search(4)); // undefined
console.log(sl.search(1)); // 'one'

