// RESERVOIR SAMPLING — Algorithm R — O(n) time, O(k) space
function reservoirSample(stream, k) {
    const reservoir = [];
    for (let i = 0; i < stream.length; i++) {
        if (i < k) {
            reservoir.push(stream[i]); // fill reservoir with first k
        } else {
            // Keep stream[i] with probability k/(i+1)
            const j = Math.floor(Math.random() * (i + 1));
            if (j < k) reservoir[j] = stream[i]; // replace random item
        }
    }
    return reservoir;
}

// VERIFY UNIFORMITY: each element should appear k/n = 0.1 times on average
function verifyUniformity(streamSize = 100, k = 10, trials = 10000) {
    const counts = new Array(streamSize).fill(0);
    const stream = Array.from({length: streamSize}, (_,i) => i);
    for (let t = 0; t < trials; t++) {
        for (const item of reservoirSample(stream, k)) counts[item]++;
    }
    // Each element should appear in about k/streamSize * trials = 1000 samples
    const expected = k / streamSize * trials;
    const maxDeviation = Math.max(...counts.map(c => Math.abs(c - expected)));
    console.log(`Expected: ${expected}, Max deviation: ${maxDeviation.toFixed(0)}`);
    // Max deviation should be << expected (e.g., < 100 = 10%)
}
verifyUniformity();

