// Pick a random node from a linked list without knowing the length
class Solution {
    constructor(head) { this.head = head; }

    getRandom() {
        let result = null, curr = this.head, i = 1;
        while (curr) {
            if (Math.floor(Math.random() * i) === 0) result = curr.val;
            curr = curr.next;
            i++;
        }
        return result; // Each node has probability 1/n of being selected
    }
}
// This is k=1 reservoir sampling: keep current with prob 1/i
