// MONTE CARLO PI ESTIMATION
function estimatePi(n) {
    let inside = 0;
    for (let i = 0; i < n; i++) {
        const x = Math.random(), y = Math.random();
        if (x*x + y*y <= 1) inside++;
    }
    return 4 * inside / n;
}

