// CARTER-WEGMAN UNIVERSAL HASH FAMILY
class UniversalHash {
    constructor(m, p = 1000000007) {
        this.m = m; // table size
        this.p = p; // prime > universe size
        // Random a in [1, p-1] and b in [0, p-1]
        this.a = 1 + Math.floor(Math.random() * (p - 1));
        this.b = Math.floor(Math.random() * p);
    }

    hash(x) {
        return ((this.a * x + this.b) % this.p) % this.m;
    }
}

// VERIFY UNIVERSAL PROPERTY: P(collision) <= 1/m
function testUniversality(m = 100, trials = 100000) {
    let collisions = 0;
    for (let t = 0; t < trials; t++) {
        const h = new UniversalHash(m);
        // Pick any two distinct keys
        const x = Math.floor(Math.random() * 1000);
        let y = Math.floor(Math.random() * 1000);
        while (y === x) y = Math.floor(Math.random() * 1000);
        if (h.hash(x) === h.hash(y)) collisions++;
    }
    const actualRate = collisions / trials;
    console.log(`Collision rate: ${actualRate.toFixed(4)}, 1/m = ${(1/m).toFixed(4)}`);
    // Should be approximately 1/m = 0.01
}
testUniversality(100);

// PERFECT HASHING (two-level) — O(n) space, O(1) worst-case lookup
function buildPerfectHash(keys) {
    const n = keys.length;
    const firstLevel = new UniversalHash(n);
    const buckets = Array.from({length:n}, ()=>[]);
    for (const k of keys) buckets[firstLevel.hash(k)].push(k);

    // Second level: for each bucket of size k_i, use hash table of size k_i^2
    const secondLevel = buckets.map(bucket => {
        const size = bucket.length ** 2 || 1;
        let h, collision;
        do { // retry until no collision
            h = new UniversalHash(size);
            const seen = new Set();
            collision = false;
            for (const k of bucket) {
                const pos = h.hash(k);
                if (seen.has(pos)) { collision = true; break; }
                seen.add(pos);
            }
        } while (collision);
        // Build table
        const table = new Array(size).fill(null);
        for (const k of bucket) table[h.hash(k)] = k;
        return {h, table};
    });

    return {firstLevel, secondLevel};
}

