// RANDOM PICK WITH WEIGHT (#528)
class WeightedRandom {
    constructor(w) {
        this.prefix = [0];
        for (const x of w) this.prefix.push(this.prefix.at(-1) + x);
        this.total = this.prefix.at(-1);
    }

    pickIndex() {
        const r = Math.random() * this.total;
        // Binary search for first prefix > r
        let lo = 1, hi = this.prefix.length - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (this.prefix[mid] <= r) lo = mid + 1;
            else hi = mid;
        }
        return lo - 1;
    }
}
